import{b as e,O as t,g as r,j as a}from"./chunks/framework.DcaUmd3X.js";const _=JSON.parse('{"title":"Chrome 控制台打开太慢解决方案","description":"","frontmatter":{"tags":["工具","浏览器","Chrome"]},"headers":[],"relativePath":"blog/tools/chrome-devtools-slow-fix/index.md","filePath":"个人博客/工具篇/3.chrome控制台打开太慢解决方案.md","lastUpdated":1781623812000}'),d={name:"blog/tools/chrome-devtools-slow-fix/index.md"};function l(s,o,h,i,n,c){return t(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="chrome-控制台打开太慢解决方案" tabindex="-1">Chrome 控制台打开太慢解决方案 <a class="header-anchor" href="#chrome-控制台打开太慢解决方案" aria-label="Permalink to &quot;Chrome 控制台打开太慢解决方案&quot;">​</a></h1><h2 id="问题描述" tabindex="-1">问题描述 <a class="header-anchor" href="#问题描述" aria-label="Permalink to &quot;问题描述&quot;">​</a></h2><p>Chrome 开发者工具（DevTools）打开时卡顿 3~4 秒，窗口才能正常显示。遇到线上问题急需看报错时，等这几秒非常影响效率。</p><h2 id="原因分析" tabindex="-1">原因分析 <a class="header-anchor" href="#原因分析" aria-label="Permalink to &quot;原因分析&quot;">​</a></h2><p>Chrome DevTools 的语言包是按需加载的。如果 Chrome 界面语言设置为 <strong>English (UK)</strong>，其对应的语言包体积较大，加载时会导致 DevTools 窗口出现明显延迟。</p><blockquote><p>English (UK) 语言包包含了大量本地化字符串，解析和加载时间比 English (US) 长，是导致这个问题的常见原因。</p></blockquote><h2 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h2><p>将 Chrome 语言从 <code>English (UK)</code> 切换为 <code>English (US)</code>：</p><ol><li>打开 Chrome 开发者工具（<code>F12</code> 或 <code>Cmd + Option + I</code>）</li><li>点击右上角 <strong>齿轮图标</strong>（设置）</li><li>左侧菜单找到 <strong>Preferences</strong> → <strong>Language</strong></li><li>将语言从 <code>English (UK)</code> 修改为 <strong>English (US)</strong></li><li>关闭 DevTools 重新打开，延迟消失</li></ol><blockquote><p>修改后 Chrome 界面语言不变，仅影响 DevTools 的语言包加载。</p></blockquote><h2 id="其他可能原因" tabindex="-1">其他可能原因 <a class="header-anchor" href="#其他可能原因" aria-label="Permalink to &quot;其他可能原因&quot;">​</a></h2><p>如果改完语言还是慢，排查以下几点：</p><table tabindex="0"><thead><tr><th>原因</th><th>排查方式</th></tr></thead><tbody><tr><td>扩展程序干扰</td><td>开无痕窗口（<code>Cmd + Shift + N</code>）打开 DevTools，如果变快就是扩展问题</td></tr><tr><td>缓存过大</td><td>DevTools 设置 → Experiments → 勾选 &quot;Purge DevTools cache on reload&quot;</td></tr><tr><td>旧版本 Bug</td><td>确认 Chrome 更新到最新版（<code>chrome://settings/help</code>）</td></tr><tr><td>硬件加速</td><td>设置 → 系统 → 关闭&quot;使用硬件加速模式&quot;试试</td></tr><tr><td>页面本身太重</td><td>复杂 SPA 页面 DevTools 初始化本身就慢，换个简单页面验证</td></tr></tbody></table>',13)])])}const g=e(d,[["render",l]]);export{_ as __pageData,g as default};
